from scipy.optimize import least_squares
def model(q):
    a,b,c0,c1,A,w,B,k,d=q
    h=c0+c1*t+A*np.sin(w*t)+B*np.cos(w*t)+d*np.exp(-k*t)
    return a*t+b*P*np.log(P)+h/P
def res(q): return (model(q)-dP_dt)
best=None
for w0 in [0.33,0.35,0.36,0.4,0.5,0.6]:
    for k0 in [0.5,1,2]:
        r=least_squares(res,[0.65,0.55,-3.5,1,3.9,w0,2.3,k0,1.8],method='lm' if False else 'trf',max_nfev=5000)
        nm=np.mean(r.fun**2)/np.var(dP_dt)
        if best is None or nm<best[0]: best=(nm,r.x)
print(best)
